mapper.select:
SELECT EXISTS (
  SELECT 1
  FROM ${requestResource} mr
  INNER JOIN msf_request_cstmr mrc
  ON mr.request_key = mrc.request_key
  WHERE mr.request_key::text = #{request.requestKey}


      AND SUBSTRING(mrc.cstmr_native_birth::text, 3, 6) = #{request.password}


      AND SUBSTRING(mrc.cstmr_foreigner_birth::text, 3, 6) = #{request.password}


      AND LEFT(mrc.cstmr_juridical_rrn::text, 10) = #{request.password}


      AND LEFT(mrc.cstmr_private_biz_no::text, 10) = #{request.password}


)
